static char* mime_file_type(const char* filename, MimeClosure stream_closure) {
  char* retType = nullptr;
  char* ext = nullptr;
  nsresult rv;

  ext = PL_strrchr(filename, '.');
  if (ext) {
    ext++;
    nsCOMPtr<nsIMIMEService> mimeFinder(
        do_GetService(NS_MIMESERVICE_CONTRACTID, &rv));
    if (mimeFinder) {
      nsAutoCString type;
      rv = mimeFinder->GetTypeFromExtension(nsDependentCString(ext), type);
      // Never return an empty MIME type.
      if (NS_SUCCEEDED(rv) && !type.IsEmpty()) {
        retType = ToNewCString(type);
      }
    }
  }

  return retType;
}
